package com.smartstock;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import android.text.*;import android.webkit.*;import android.print.*;import com.journeyapps.barcodescanner.*;import java.io.*;import java.math.*;import java.util.*;
public class MainActivity extends Activity {
 Book book; Book.Item selected; LinearLayout root,detail; EditText search,qty; TextView stats,preview; WebView printView; File source; boolean busy;
 @Override public void onCreate(Bundle b){super.onCreate(b);source=new File(getFilesDir(),"source.xlsx");ui();if(source.exists())load(Uri.fromFile(source),false);}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setPadding(8,10,8,10);return t;}
 void button(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());l.addView(b);}
 void msg(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("حسناً",null).show();}
 void ui(){ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,24,24,24);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);sc.addView(root);setContentView(sc);root.addView(label("SMART STOCK | الجرد الذكي",25));stats=label("استورد ملف Excel للبدء",16);root.addView(stats);button(root,"استيراد ملف جديد",()->{if(busy)return;new AlertDialog.Builder(this).setMessage("بدء ملف جديد يستبدل الجلسة الحالية. صدّرها أولاً.").setPositiveButton("اختيار الملف",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);}).setNegativeButton("إلغاء",null).show();});search=new EditText(this);search.setSingleLine();search.setHint("الباركود أو اسم الصنف");root.addView(search);search.setOnEditorActionListener((v,a,e)->{find();return true;});button(root,"بحث",this::find);button(root,"مسح بالكاميرا",()->{if(book==null||busy)return;new IntentIntegrator(this).setOrientationLocked(false).setPrompt("امسح باركود الصنف").initiateScan();});detail=new LinearLayout(this);detail.setOrientation(1);root.addView(detail);button(root,"تصدير Excel",()->{if(book==null||busy)return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");i.putExtra(Intent.EXTRA_TITLE,"جرد-نهائي.xlsx");startActivityForResult(i,2);});button(root,"طباعة جميع الأصناف + التقرير A4",this::print);}
 void load(Uri uri,boolean fresh){if(busy)return;busy=true;stats.setText("جاري قراءة الملف...");new Thread(()->{try{File tmp=new File(getFilesDir(),"incoming.xlsx");if(fresh){try(InputStream in=getContentResolver().openInputStream(uri);OutputStream o=new FileOutputStream(tmp)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)o.write(b,0,n);}}Book next=new Book(new FileInputStream(fresh?tmp:source));if(fresh){if(!tmp.renameTo(source))throw new IOException("تعذر حفظ الملف");getSharedPreferences("counts",0).edit().clear().commit();}else for(Book.Item p:next.items){String v=getSharedPreferences("counts",0).getString("r"+p.row,null);if(v!=null){p.qty=new BigInteger(v);p.counted=true;}}runOnUiThread(()->{book=next;selected=null;detail.removeAllViews();busy=false;refresh();});}catch(Exception e){runOnUiThread(()->{busy=false;refresh();msg(e.toString());});}}).start();}
 void refresh(){if(book==null){stats.setText("لا يوجد ملف نشط");return;}BigInteger q=BigInteger.ZERO;BigDecimal t=BigDecimal.ZERO;int c=0;for(Book.Item p:book.items){q=q.add(p.qty);t=t.add(p.total());if(p.counted)c++;}stats.setText("الأصناف: "+book.items.size()+" | المجرودة: "+c+"\nالكمية: "+q+" | الإجمالي: "+t.toPlainString());}
 void find(){if(book==null||busy)return;String s=search.getText().toString().trim();if(s.isEmpty())return;List<Book.Item> a=book.index.get(s);if(a==null){a=new ArrayList<>();for(Book.Item p:book.items)if(p.data[1].contains(s))a.add(p);}if(a.isEmpty()){msg("الصنف غير موجود");return;}if(a.size()==1){show(a.get(0));return;}final List<Book.Item> list=a;String[] names=new String[a.size()];for(int i=0;i<a.size();i++){Book.Item p=a.get(i);names[i]=p.data[1]+" | "+p.data[0]+" | صف "+p.row+" | "+p.cost;}new AlertDialog.Builder(this).setTitle("اختر الصنف المطابق").setItems(names,(d,w)->show(list.get(w))).show();}
 void show(Book.Item p){selected=p;detail.removeAllViews();String[] labels={"المجموعة","الصنف","الوحدة","العبوة","الباركود"};for(int i=0;i<5;i++)detail.addView(label(labels[i]+": "+p.data[i],17));detail.addView(label("التكلفة: "+p.cost.toPlainString()+" | الكمية السابقة: "+p.qty,18));qty=new EditText(this);qty.setInputType(2);qty.setHint("الكمية الإضافية");detail.addView(qty);preview=label("الإجمالي: "+p.total().toPlainString(),20);detail.addView(preview);qty.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){try{preview.setText("الإجمالي بعد الإضافة: "+p.cost.multiply(new BigDecimal(p.qty.add(new BigInteger(s.toString())))).toPlainString());}catch(Exception e){preview.setText("أدخل كمية صحيحة");}}public void afterTextChanged(Editable e){}});button(detail,"حفظ وإضافة الكمية",()->{if(busy||selected!=p)return;try{BigInteger n=new BigInteger(qty.getText().toString());if(n.signum()<0)throw new Exception();save(p,p.qty.add(n));}catch(Exception e){msg("تعذر الحفظ: تحقق من الكمية");}});button(detail,"تصحيح الكمية التراكمية",()->{EditText e=new EditText(this);e.setInputType(2);e.setText(p.qty.toString());new AlertDialog.Builder(this).setTitle("الكمية الصحيحة النهائية").setView(e).setPositiveButton("تصحيح",(d,w)->{try{BigInteger n=new BigInteger(e.getText().toString());if(n.signum()<0)throw new Exception();save(p,n);}catch(Exception ex){msg("تعذر التصحيح");}}).setNegativeButton("إلغاء",null).show();});qty.requestFocus();}
 void save(Book.Item p,BigInteger n)throws Exception{if(!getSharedPreferences("counts",0).edit().putString("r"+p.row,n.toString()).commit())throw new IOException();p.qty=n;p.counted=true;selected=null;detail.removeAllViews();search.setText("");search.requestFocus();refresh();Toast.makeText(this,"تم الحفظ",Toast.LENGTH_SHORT).show();}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);IntentResult scan=IntentIntegrator.parseActivityResult(r,c,d);if(scan!=null){if(scan.getContents()!=null){search.setText(scan.getContents());find();}return;}if(c!=RESULT_OK||d==null)return;if(r==1)load(d.getData(),true);if(r==2&&book!=null){try(OutputStream o=getContentResolver().openOutputStream(d.getData())){book.export(o);msg("تم تصدير الملف");}catch(Exception e){msg(e.toString());}}}
 static String esc(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
 void print(){if(book==null||busy)return;StringBuilder h=new StringBuilder("<html dir='rtl'><meta charset='utf-8'><style>@page{size:A4 landscape;margin:12mm}body{font-family:sans-serif;font-size:11px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aaa;padding:5px}thead{display:table-header-group}tr{page-break-inside:avoid}.summary{page-break-before:always;font-size:20px}</style><h2>كشف الجرد الفعلي</h2><table><thead><tr><th>اسم الصنف</th><th>العبوة</th><th>الباركود</th><th>الكمية</th><th>التكلفة</th><th>الإجمالي</th></tr></thead><tbody>");BigInteger q=BigInteger.ZERO;BigDecimal t=BigDecimal.ZERO;int c=0;for(Book.Item p:book.items){h.append("<tr>");for(String s:new String[]{p.data[1],p.data[3],p.data[4],p.qty.toString(),p.cost.toPlainString(),p.total().toPlainString()})h.append("<td>").append(esc(s)).append("</td>");h.append("</tr>");q=q.add(p.qty);t=t.add(p.total());if(p.counted)c++;}h.append("</tbody></table><div class='summary'><h1>التقرير النهائي للجرد</h1><p>عدد الأصناف: ").append(book.items.size()).append("</p><p>الأصناف المجرودة: ").append(c).append("</p><p>إجمالي الكميات: ").append(q).append("</p><p>الإجمالي المالي: ").append(t.toPlainString()).append("</p></div></html>");printView=new WebView(this);printView.setWebViewClient(new WebViewClient(){boolean done;public void onPageFinished(WebView v,String url){if(done)return;done=true;((PrintManager)getSystemService(PRINT_SERVICE)).print("كشف الجرد",v.createPrintDocumentAdapter("كشف الجرد"),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4.asLandscape()).build());}});printView.loadDataWithBaseURL(null,h.toString(),"text/html","UTF-8",null);}
}
